const inputData = $input.first().json;
const body = inputData.body || inputData;
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const accountId = body.account_id || 'aa000000-0000-0000-0000-000000000001';
const amountNum = Number(body.amount) || 1000;

return [{
  json: {
    isValid: true,
    params: {
      account_id: String(accountId).trim(),
      amount: amountNum,
      currency: String(body.currency || 'USD').trim().toUpperCase(),
      profile_id: body.profile_id ? String(body.profile_id).trim() : null,
      transaction_context: body.transaction_context || {}
    }
  }
}];

const item = $input.first().json;

// Safety rule: NEVER silently approve if fraud service fails
if (!item || typeof item !== 'object' || item.error || (item.approved === undefined && item.risk_score === undefined)) {
  return [{
    json: {
      isSchemaValid: false,
      approved: false,
      risk_score: 100.0,
      decision: 'HOLD',
      reason: 'Python fraud service unavailable or returned invalid schema (Safety Lock triggered)',
      fraud_assessment_id: null
    }
  }];
}

const riskScore = Number(item.risk_score || 0);
const approved = item.approved === true && riskScore < 75;
let decision = 'CLEAR';
if (riskScore >= 75 || !approved) {
  decision = 'HOLD';
} else if (riskScore >= 40) {
  decision = 'REVIEW';
}

return [{
  json: {
    isSchemaValid: true,
    approved,
    risk_score: riskScore,
    decision,
    reason: item.reason || 'Fraud assessment complete',
    fraud_assessment_id: item.fraud_assessment_id || 'fa000000-0000-0000-0000-000000000001'
  }
}];

