// Turn the numbers into the kind of sentence an investigator would write, so
// that a semantic search against the fraud-pattern index actually matches on
// behaviour rather than on digits. Embeddings do nothing useful with "amount:
// 75000000"; they do a lot with "a very large transfer to a destination never
// paid before".
const v = $('Validate & Evaluate Fraud Decision').first().json;
const p = $('Validate Request Payload').first().json.params || {};
const ctx = p.transaction_context || {};

const amount = Number(p.amount || 0);
const rupees = amount / 100;
const parts = [];

if (rupees >= 500000) parts.push('a very large transfer of Rs ' + rupees.toFixed(2));
else if (rupees >= 100000) parts.push('a large transfer of Rs ' + rupees.toFixed(2));
else parts.push('a transfer of Rs ' + rupees.toFixed(2));

const reason = String(v.reason || '').toLowerCase();
if (reason.includes('velocity') || reason.includes('transactions in')) {
  parts.push('one of many transfers from this account in a short window');
}
if (reason.includes('new recipient') || reason.includes('never')) {
  parts.push('sent to a destination account that has never been paid before');
}
if (reason.includes('frozen') || reason.includes('hold')) {
  parts.push('attempted on an account that already had a hold on it');
}
if (ctx.joint_action_ref) {
  parts.push('on a joint account requiring all holders to sign');
}

parts.push('risk score ' + (v.risk_score || 0) + ' out of 100');

return [{ json: {
  query: parts.join(', ') + '. What known fraud pattern does this resemble?',
  risk_score: v.risk_score,
  reason: v.reason
} }];

// Collapse the retrieved patterns into a block the ops alert can paste in.
// Runs once for all matches, and degrades to a plain note rather than failing
// if the lookup returned nothing.
const items = $input.all().map(i => i.json).filter(Boolean);

const texts = [];
for (const it of items) {
  const doc = it.document || it;
  const content = doc.pageContent || doc.text || '';
  const meta = doc.metadata || {};
  if (content) {
    texts.push({ doc_id: meta.doc_id || 'pattern', content: String(content).trim() });
  }
}

let block;
if (texts.length === 0) {
  block = 'No matching pattern was retrieved. Assess this one on the transaction detail above.';
} else {
  block = texts.map((t, i) =>
    (i + 1) + '. [' + t.doc_id + ']\n' + t.content
  ).join('\n\n');
}

return [{ json: {
  pattern_block: block,
  pattern_count: texts.length,
  matched_doc_ids: texts.map(t => t.doc_id).join(', ') || 'none'
} }];
